        return min(n * n, maxWeight // w)

#include <algorithm>

using namespace std;

class Solution {
public:
    int maxContainers(int n, int w, int maxWeight) {
        return min((long long)n * n, (long long)maxWeight / w);
    }
};

class Solution {
    public int maxContainers(int n, int w, int maxWeight) {
        return (int) Math.min((long) n * n, (long) maxWeight / w);
    }
}

var maxContainers = function(n, w, maxWeight) {
    const spaceCapacity = n * n;
    const weightCapacity = Math.floor(maxWeight / w);
    return Math.min(spaceCapacity, weightCapacity);
};
